namespace ghidra.feature.vt.gui.actions;





using docking;
using docking.action;
using docking.tool;
using ghidra.feature.vt.gui.plugin;
using ghidra.util;
using ghidra.util;
using help;
using help;
using resources;
using resources;

public class HelpAction : DockingAction {

	private static Icon ICON = Icons.HELP_ICON;

	public HelpAction() : base("Version Tracking Help Action", VTPlugin.OWNER)
    {

		string[] menuPath = new string[] { ToolConstants.MENU_HELP, "Workflow" };
		setMenuBarData(new MenuData(menuPath, ICON, "AAAHelpContents"));
		setToolBarData(new ToolBarData(ICON, "ZZZ"));
		setHelpLocation(new HelpLocation("VersionTrackingPlugin", "Version_Tracking_Tool"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {

		HelpService help = Help.getHelpService();
		if (help == null) {
			Msg.showError(this, null, "Help Not Found",
				"HelpManager failed to initialize properly");
			return;
		}

		URL url =
			ResourceManager.getResource("help/topics/VersionTrackingPlugin/VT_Workflow.html");
		if (url == null) {
			Msg.showError(this, null, "Help Not Found",
				"Unable to find the Version Tracking workflow help");
			return;
		}

		help.showHelp(url);
	}

}
